import{_ as t,c as o,o as a,al as l}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"Test MC_07 - Optical Flow Low Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_cards/mc_07_optical_flow_low_mount.md","filePath":"en/test_cards/mc_07_optical_flow_low_mount.md"}'),i={name:"en/test_cards/mc_07_optical_flow_low_mount.md"};function r(n,e,s,c,h,d){return a(),o("div",null,e[0]||(e[0]=[l('<h1 id="test-mc-07-optical-flow-low-sensor" tabindex="-1">Test MC_07 - Optical Flow Low Sensor <a class="header-anchor" href="#test-mc-07-optical-flow-low-sensor" aria-label="Permalink to &quot;Test MC_07 - Optical Flow Low Sensor&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that optical flow works as expected with a low mounted optical flow sensor</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Ensure that the drone&#39;s optical flow sensor is mounted more than an inch off of the ground</p><p>Ensure that <a href="./../advanced_config/parameter_reference.html#MPC_THR_MIN">MPC_THR_MIN</a> is tuned correctly for landing</p><p>Disconnect all GPS / compasses and ensure vehicle is using optical flow for navigation (<a href="./../sensor/optical_flow.html">Setup Information here</a>)</p><p>Ensure there are no other sources of positioning besides optical flow</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li></ul><p>Ensure that the drone can go into <a href="./../flight_modes_mc/position.html">Position mode</a> while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/position.html">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="landing" tabindex="-1">Landing <a class="header-anchor" href="#landing" aria-label="Permalink to &quot;Landing&quot;">​</a></h2><p>❏ Land in Position mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="expected-results" tabindex="-1">Expected Results <a class="header-anchor" href="#expected-results" aria-label="Permalink to &quot;Expected Results&quot;">​</a></h2><ul><li>Take-off should be smooth as throttle is raised</li><li>Drone should stay in Position mode, NOT fall into <a href="./../flight_modes_mc/altitude.html">altitude</a> mode</li></ul>',21)]))}const f=t(i,[["render",r]]);export{p as __pageData,f as default};
